[6121] = { en = "Lessons Anew", tier = 1,
  t = "Opnieuw lessen",
  d = "Je bent nu klaar om te leren over gif, $N, en over de macht die wij als druïden erover hebben. Cenarius heeft ons een gave gegeven. We kunnen zelfs het ergste gif wegnemen met maar één spreuk. Denk niet licht over deze gave... En om zeker te zijn dat je deze les leert, ga je de gevolgen van vergiftiging aanpakken zoals een gewoon iemand dat zou doen.$B$BReis naar Moonglade en praat met Dendrite Starblaze. Hij wacht op je om met je les te beginnen.",
  o = "Reis naar Moonglade en praat met Dendrite Starblaze in het dorp Nighthaven.",
  c = "Gegroet, jonge $C. Ik ben blij dat je klaar bent en graag wilt leren over het genezen van gif.$B$BVroeger moesten de meeste druïden proeven doen die al gepland waren. Jouw werk is niet zo. In Auberdine zijn de laatste tijd veel dieren vergiftigd. Het dorp daar kan het niet genezen. Daarom heeft iemand uit het dorp Moonglade om hulp gevraagd. Wij sturen jou om hen te helpen. Dit is geen oefening. Het werk dat je gaat doen, is echt. Denk daaraan.",
  g = { {"gif", "poison"}, {"druïden", "druids (druïde)"}, {"gave", "gift, talent"}, {"ergste", "worst"}, {"spreuk", "spell, incantation"}, {"gevolgen", "effects, consequences"}, {"vergiftiging", "poisoning"}, {"aanpakken", "to tackle, to deal with"}, {"gegroet", "greetings"}, {"genezen", "to cure, to heal"}, {"proeven", "trials (proef)"}, {"gepland", "planned (plannen)"}, {"vergiftigd", "poisoned (vergiftigen)"}, {"oefening", "exercise"} },
},

[6122] = { en = "The Principal Source", tier = 1,
  t = "De belangrijkste bron",
  d = "De Cliffspring Falls in Darkshore zijn de belangrijkste bron van drinkwater voor het gebied. Nu denk ik dat ze ook de belangrijkste bron zijn van het gif dat de dieren hier ziek maakt, vooral de herten. Gebruik dit monsterflesje om wat water te halen bij de ingang van de grot. Wees voorzichtig: in een grot bij de waterval wonen nu gevaarlijke naga.$B$BAls het flesje vol is, breng je het naar Alanndarian Nightsong in Auberdine. Zij heeft om onze hulp gevraagd. Samen met haar ga je deze ziekte aanpakken.",
  o = "Gebruik de Empty Cliffspring Falls Sampler om wat water te halen bij de ingang van de grot bij de waterval.$B$BBreng de Filled Cliffspring Falls Sampler naar Alanndarian Nightsong in Auberdine, Darkshore.",
  p = "Heeft de Cenarion Circle in Moonglade jou gestuurd? Wat fijn! We hebben hier een grote crisis met de arme herten. We zijn blij met alle hulp die we kunnen krijgen.$B$BHeb je het watermonster waar Dendrite Starblaze over sprak? Hij liet me weten dat je er een zou halen. Dan kunnen we samen aan een medicijn werken...",
  c = "Bij Elune, wat is dit water vies! Geen wonder dat de herten ziek zijn.$B$BIets maakt het water vuil. Zo bederft het ook al het grondwater van Darkshore. Overal in het gebied zijn zieke herten gezien, en niet alleen bij de rivier. Dit water is waarschijnlijk een belangrijke bron van de ziekte die zich verspreidt. Maar er is hier nog iets anders aan de hand.$B$BGeloof het of niet, maar dit water helpt ons om een medicijn te maken. Terwijl ik dit water onderzoek, heb ik wat spullen nodig voor het medicijn...",
  g = { {"bron", "source, spring"}, {"drinkwater", "drinking water"}, {"herten", "deer (hert)"}, {"monsterflesje", "sample flask, sampler"}, {"ingang", "entrance, mouth"}, {"waterval", "waterfall"}, {"crisis", "crisis"}, {"watermonster", "water sample"}, {"medicijn", "cure, medicine"}, {"bederft", "spoils, corrupts (bederven)"}, {"grondwater", "groundwater, water table"}, {"verspreidt", "spreads (verspreiden)"}, {"aan de hand", "going on"}, {"onderzoek", "research, examine (onderzoeken)"} },
},

[6123] = { en = "Gathering the Cure", tier = 1,
  t = "Het medicijn verzamelen",
  d = "Het water wordt de basis van de genezende zalf die ik voor de herten maak. Om te genezen heb ik wat Earthroot nodig. Kruidenkenners weten hoe ze het kunnen vinden. Als we pech hebben en jij er geen bent, moet je er een zoeken die ons helpt.$B$BTot slot heb ik voor de kracht wat Lunar Fungus nodig. Lunar Fungus vinden is makkelijk genoeg. Het groeit overal in de grotten net ten oosten van hier. In die grotten wonen moonkin, en die zijn de laatste tijd snel boos. Wees dus voorzichtig.",
  o = "Breng 5 Earthroot en 12 Lunar Funguses naar Alanndarian Nightsong in Auberdine. Dan kan ze een genezende zalf maken.",
  p = "Heb je de ingrediënten die ik nodig heb voor de zalf? De herten worden niet vanzelf beter. We moeten opschieten om ze te helpen!",
  c = "Dit is goed, $N. Het is zelfs genoeg voor een flink aantal porties zalf. Dat is in elk geval genoeg om een verschil te gaan maken.$B$BEen medicijn tegen gif maken is soms heel moeilijk. Voor elk gif heb je vaak een heel speciaal tegengif nodig. Stel je voor dat je elk gif kunt genezen wanneer je wilt! Dan hoef je je geen zorgen te maken over wat er precies in het tegengif moet!$B$BNu, laat me aan het werk gaan!",
  g = { {"genezende", "healing, curative"}, {"zalf", "salve, ointment"}, {"kruidenkenners", "herbalists (kruidenkenner)"}, {"pech", "bad luck"}, {"tot slot", "finally"}, {"groeit", "grows (groeien)"}, {"ten oosten van", "east of"}, {"ingrediënten", "ingredients, reagents"}, {"vanzelf", "by themselves"}, {"opschieten", "to hurry"}, {"porties", "doses, portions (portie)"}, {"tegengif", "antidote"}, {"stel je voor", "imagine"} },
},

[6124] = { en = "Curing the Sick", tier = 1,
  t = "De zieken genezen",
  d = "Met de ingrediënten die je bracht, heb ik genoeg zalf voor tien porties, $N. Ik ga met het dorp proberen meer zalf te maken. Ondertussen wil ik dat jij ons alvast helpt. Overal in Darkshore zijn zieke herten. Gebruik de zalf op ze en genees ze van hun ziekte.$B$BDendrite Starblaze in Moonglade wil je vast spreken als je klaar bent. Wil je de Cenarion Circle daar bedanken namens Auberdine? En ik wil jou zelf ook bedanken voor je hulp!",
  o = "Gebruik de Curative Animal Salve op 10 Sickly Deer in Darkshore. Zo genees je ze. Er zijn Sickly Deer gezien vanaf het zuiden van de Cliffspring River, ten noorden van Auberdine. Ze zitten helemaal tot in het zuiden van Darkshore, waar de rand van Ashenvale begint.",
  p = "Heb je gedaan wat Alanndarian Nightsong van Auberdine je vroeg? Anders is je werk niet klaar.",
  c = "Je hebt goed voor de zieke herten van Darkshore gezorgd. Ze weten het zelf niet, maar ze zijn slachtoffers van een groter kwaad en bederf. Dat verspreidt zich over het hele land. Sommigen in Darnassus zien dit gevaar... en anderen negeren de groeiende tekenen. Ik hoop dat jij je ogen niet sluit voor de feiten die recht voor je liggen, $N.$B$BHoe dan ook, je hebt laten zien dat je een vriend van de natuur en de Circle bent. Neem dit als teken daarvan.",
  o1 = "Sickly Deer genezen",
  g = { {"ondertussen", "meanwhile"}, {"alvast", "already, in advance"}, {"genees", "cure (genezen)"}, {"namens", "on behalf of"}, {"rand", "edge"}, {"gezorgd", "taken care (zorgen)"}, {"slachtoffers", "victims (slachtoffer)"}, {"kwaad", "evil, harm"}, {"bederf", "corruption, decay"}, {"negeren", "to ignore"}, {"tekenen", "signs (teken)"}, {"feiten", "facts (feit)"}, {"hoe dan ook", "regardless, anyway"} },
},

[6125] = { en = "Power over Poison", tier = 1,
  t = "Macht over gif",
  d = "Je hebt geleerd hoe het is om gif te genezen zonder spirituele hulp. Denk aan wat anderen moeten doorstaan als ze tegen gif vechten. Want jij krijgt nu zelf macht over gif.$B$BGa nu terug naar Mathrengyl Bearwalker in Darnassus, $N. Hij heeft vast een heel belangrijke spreuk voor je, nu de leerling de les begrijpt die $ghij:zij; heeft gekregen.$B$BVaarwel, jonge druïde. We spreken elkaar nog.",
  o = "Ga terug naar Mathrengyl Bearwalker in de Cenarion Enclave, Darnassus.",
  c = "Welkom terug. Ik heb je voortgang gevolgd sinds je vertrok. Ik moet zeggen dat ik verrast was over de situatie in Auberdine. Dit moeten we verder onderzoeken. Zulk gif in de natuur brengt het evenwicht erg van slag.$B$BJe bleef rustig en sterk onder druk. Daarvoor is er geen betere beloning dan blijvende macht over gif. Gebruik het goed, $N... gebruik het goed.",
  g = { {"spirituele", "spiritual"}, {"doorstaan", "to endure"}, {"leerling", "student, pupil"}, {"vaarwel", "farewell"}, {"voortgang", "progress"}, {"verrast", "surprised (verrassen)"}, {"evenwicht", "balance"}, {"van slag", "upset, out of balance"}, {"onder druk", "under pressure"}, {"beloning", "reward"}, {"blijvende", "permanent, lasting"} },
},

[26] = { en = "A Lesson to Learn", tier = 1,
  t = "Een les om te leren",
  d = "$N, ik heb je voortgang met veel plezier gevolgd. Je wordt echt een waardevolle beschermer van de natuur.$B$BHet is tijd om meer te leren over een van de verschillende dierlijke vormen. Cenarius heeft ons de gave gegeven om in deze dieren te veranderen. Deze vorm geeft je controle en meesterschap over het water. Daarvoor moet je naar het dorp Nighthaven in Moonglade reizen. Praat daar met Dendrite Starblaze van de Cenarion Circle. Hij helpt je verder.",
  o = "Praat met Dendrite Starblaze in het dorp Nighthaven, Moonglade.",
  c = "Gegroet, jonge $C. Het is tijd dat je onze watervorm leert kennen. Met deze vorm beweeg je vrij en zonder einde door het water. Je zult merken dat deze vorm een nuttig hulpmiddel is en een zegen... maar je moet hem eerst verdienen voordat je hem beheerst.$B$BJe krijgt twee proeven. De eerste test of je onder druk in het water kunt werken. De tweede test je wil om de vorm zelf goed te begrijpen.$B$BWees klaar, want de tijd van de proeven is nu gekomen.",
  g = { {"waardevolle", "valued, valuable"}, {"beschermer", "protector"}, {"dierlijke", "animal (adj.)"}, {"controle", "control, command"}, {"meesterschap", "mastery"}, {"watervorm", "aquatic form"}, {"nuttig", "useful"}, {"hulpmiddel", "tool, aid"}, {"zegen", "blessing"}, {"verdienen", "to earn"}, {"beheerst", "master (beheersen)"} },
},

[29] = { en = "Trial of the Lake", tier = 1,
  t = "De Proef van het Meer",
  d = "Voor je eerste proef zoek je in de diepte van Lake Elune'ara naar een Shrine Bauble. Het sieraad vergaat snel, dus ga er zo snel mogelijk mee naar de Shrine of Remulos. Gebruik het sieraad bij het heiligdom en praat daarna met Tajarri. Zij is een van de meest vertrouwde wachters van Moonglade.$B$BJe hebt maar een beperkte tijd voor deze taak. Misschien moet je het ook opnemen tegen andere druïden die zelf naar zulke sieraden zoeken. Een snelle geest en een behendig lichaam zijn heel belangrijk voor je succes.$B$BSucces, $N.",
  o = "Zoek een Shrine Bauble in Lake Elune'ara en breng het naar de Shrine of Remulos in het noordwesten van Moonglade. Gebruik daar de Shrine Bauble.$B$BDaarna moet je met Tajarri bij het heiligdom praten om de proef af te ronden.",
  p = "Om de Proef van het Meer af te ronden, moet je de Shrine Bauble binnen de grenzen van dit heiligdom gebruiken. Zolang je dat niet doet, is je proef niet af. Dan kan hij nog mislukken.",
  c = "Zo. Het lijkt erop dat weer een druïde de Proef van het Meer heeft gehaald! Goed gedaan, mijn jonge vriend. Goed gedaan.$B$BZoals ik al zei, heet ik Tajarri. Het is mijn plicht en mijn eer om wachter te zijn van Moonglade, en vooral van dit heiligdom. Keeper Remulos leidt de Cenarion Circle in het beschermen van natuur en evenwicht. Zijn heiligdom is een blijvend eerbetoon daaraan. Als je het sieraad hier gebruikt, laat je zien hoe belangrijk deze plek is voor de Circle.",
  e = "Rond de Proef van het Meer af.",
  g = { {"diepte", "depths"}, {"sieraad", "trinket, bauble"}, {"vergaat", "decays (vergaan)"}, {"heiligdom", "shrine"}, {"vertrouwde", "trusted"}, {"wachters", "wardens (wachter)"}, {"beperkte", "limited"}, {"het opnemen tegen", "to compete against"}, {"behendig", "agile, dexterous"}, {"af te ronden", "to complete, to finish (afronden)"}, {"grenzen", "boundaries (grens)"}, {"mislukken", "to fail"}, {"plicht", "duty"}, {"eer", "honour, privilege"}, {"eerbetoon", "tribute"} },
},

[272] = { en = "Trial of the Sea Lion", tier = 1,
  t = "De Proef van de Zeeleeuw",
  d = "Voor de tweede proef heb je de twee helften nodig die samen de Pendant of the Sea Lion vormen. De ene helft haalt kracht uit de behendigheid van de gedaante van de zeeleeuw, die door het water glijdt. De andere haalt kracht uit het enorme uithoudingsvermogen van de gedaante van de zeeleeuw. Druïden gebruiken beide eigenschappen evenveel om de gedaante van hun watervorm aan te nemen.$B$BPraat met de bewoners van Moonglade om te horen waar de delen kunnen liggen. Breng ze allebei hierheen om ze samen te voegen. Breng de hanger daarna naar Dendrite Starblaze.",
  o = "Zoek de Half Pendant of Aquatic Agility en de Half Pendant of Aquatic Endurance. Praat met de bewoners van Moonglade voor aanwijzingen over waar deze voorwerpen kunnen liggen.$B$BMaak de Pendant of the Sea Lion van de twee helften. Je moet dicht bij de Shrine of Remulos zijn om dit te doen.$B$BBreng de hele hanger naar Dendrite Starblaze in het dorp Nighthaven, Moonglade.",
  p = "Heb je je hanger gemaakt, zodat ik hem kan bekijken, $N? Als je hulp nodig hebt om de delen te vinden, vraag dan de bewoners hier om informatie. Je vindt dan niet alleen wat je zoekt. Je hebt ook een reden om deze prachtige en heilige open plek in het bos te verkennen.",
  c = "Je hebt de Proef van de Zeeleeuw gehaald, $n. Gefeliciteerd.$B$BElke taak om de hanger te krijgen laat zien dat je zowel behendigheid als uithoudingsvermogen nodig hebt. Alleen zo ben je in harmonie met wat je onder water wilt doen. Het ene kan niet bestaan zonder het andere. En geen van beide lukt als je de gedaante van de zeeleeuw niet wilt aannemen.$b$bOnthoud deze lessen goed. Vertrouw erop zodra je je watervorm hebt gekregen.",
  g = { {"helften", "halves (helft)"}, {"zeeleeuw", "sea lion"}, {"behendigheid", "agility"}, {"gedaante", "shape, aspect"}, {"glijdt", "glides (glijden)"}, {"uithoudingsvermogen", "endurance"}, {"eigenschappen", "traits (eigenschap)"}, {"aan te nemen", "to take on (aannemen)"}, {"bewoners", "residents (bewoner)"}, {"samen te voegen", "to join together (samenvoegen)"}, {"hanger", "pendant"}, {"aanwijzingen", "clues (aanwijzing)"}, {"heilige", "sacred, holy"}, {"verkennen", "to explore"}, {"zowel ... als", "both ... and"} },
},

[5061] = { en = "Aquatic Form", tier = 1,
  t = "Watervorm",
  d = "Je hebt de lessen gehad die alle jonge druïden krijgen voordat ze een watergedaante kunnen aannemen. Ga nu terug naar je trainer, Mathrengyl Bearwalker, in Darnassus. Laat hem je hanger zien en bewijs dat je klaar bent om te leren wat hij je moet leren. Hij maakt je training af. Dan kun je één worden met het water.$B$BTot ziens, jonge druïde. We spreken elkaar nog.",
  o = "Ga terug naar Darnassus en laat Mathrengyl Bearwalker de Pendant of the Sea Lion zien.",
  p = "Je terugkeer naar Darnassus was al aangekondigd. Toch heb ik eerst bewijs nodig van de lessen die je in Moonglade hebt geleerd. Daarna leer ik je je watervorm.$B$BHeb je de Pendant of the Sea Lion?",
  c = "Heel indrukwekkend, $N. Je bent klaar om je watervorm te leren, en ik leer hem je graag.$B$BIk geef je ook dit voorwerp, als erkenning voor wat je in de twee proeven hebt bereikt. Ik hoop dat het een fijne aanvulling is op je uitrusting als beschermer van de natuur en bewaker van het evenwicht.",
  g = { {"watergedaante", "aquatic aspect"}, {"aannemen", "to adopt, to take on"}, {"bewijs", "proof"}, {"terugkeer", "return"}, {"aangekondigd", "announced, heralded (aankondigen)"}, {"indrukwekkend", "impressive"}, {"erkenning", "recognition"}, {"bereikt", "achieved (bereiken)"}, {"aanvulling", "addition"}, {"uitrusting", "gear, equipment"}, {"bewaker", "keeper, guardian"} },
},

[2945] = { en = "Grime-Encrusted Ring", tier = 2,
  t = "De vieze ring",
  d = "Bij het lijk van een van de Dark Iron-dwergen heb je iets gevonden dat op een ring lijkt. Het is moeilijk te zien wat voor ring het is. Vuil en een harde korst zitten helemaal over het ding heen, dus je kunt hem niet dragen. Toch denk je onder de korst een zachte glans van edelmetaal te zien, en misschien zelfs de schittering van een edelsteen.$B$BAls je deze ring wilt gebruiken, moet je iets vinden om de harde korst eraf te halen.",
  o = "Zoek een manier om het vuil van de Grime-Encrusted Ring te halen.",
  p = "Op het gnomenapparaat voor je hangt een bordje met de naam \"The Sparklematic 5200\". Onder het bordje staat een handleiding. Daaruit begrijp je het belangrijkste: de machine schrobt het vuil van een voorwerp af. De machine heeft een gleuf voor munten. Als het voorwerp erin ligt, start je de machine met drie zilveren munten.$B$BDe vieze ring die je eerder vond, lijkt precies het juiste ding om in deze machine te proberen!",
  c = "Je legt de ring in de Sparklematic 5200 en stopt een zilveren munt in de gleuf.$B$BUit de machine komen pijnlijke, schurende geluiden, en hij begint wild te schokken. Je kunt alleen maar raden wat er binnenin met de ring gebeurt...$B$BOpeens stopt de machine. Met een simpel \"Ding!\" laat hij horen dat hij klaar is. Het vakje voor het voorwerp gaat open. Erin ligt een klein doosje, netjes ingepakt met een rode strik. Het lijkt erop dat de Sparklematic 5200 ook cadeautjes inpakt!",
  g = { {"lijk", "dead body, corpse"}, {"korst", "crust, hard layer"}, {"glans", "shine, lustre"}, {"edelmetaal", "precious metal"}, {"schittering", "glint, sparkle"}, {"edelsteen", "gem"}, {"handleiding", "instructions, manual"}, {"schrobt", "scrubs (schrobben)"}, {"gleuf", "slot"}, {"schurende", "grinding (schuren)"}, {"schokken", "to jerk, to jolt"}, {"vakje", "small compartment"}, {"strik", "bow (ribbon)"}, {"inpakt", "wraps (inpakken)"} },
},

[2947] = { en = "Return of the Ring", tier = 2,
  t = "De terugkeer van de ring",
  d = "Je opent het doosje van de Sparklematic 5200. Erin zit wat je al dacht: een glanzende ring! Als je de ring draagt, voel je magische kracht door je lichaam stromen.$B$BAan de binnenkant van de ring zit een kleine, maar toch duidelijke afdruk van het zegel van Ironforge. Daarnaast zijn drie kleine letters gegraveerd: \"TdK\". Dat zijn misschien de initialen van de vorige eigenaar, of misschien van de maker van de ring. Houd de ring... of breng hem terug naar deze persoon. Keuzes, keuzes...",
  o = "Je mag de ring houden, of je zoekt de persoon die de afdruk en de letters aan de binnenkant van de ring heeft gemaakt.",
  p = "Hé, rustig aan, vriend. Ik ben een heel belangrijke zakenman! Ik weet zeker dat de koerier gewoon te laat is met de huur... wacht... jij bent mijn huisbaas niet.$B$BNatuurlijk ben je dat niet, dom van me! Je komt naar mij omdat je de beste juwelier van heel Ironforge zoekt. Eentje die GEEN VERVLOEKTE spullen maakt! Ja!$B$BEh... wat heb je nodig?",
  c = "Een ring, zeg je? Eens kijken... ja hoor, die ring heb ik gemaakt, jeetje.$B$BVoordat Gnomeregan verloren ging, had ik daar een winkeltje. Misschien heb ik hem achtergelaten toen ik ervandoor ging. Het is een eenvoudig ontwerp, en ik heb er meer van gemaakt. Misschien is hij van iemand die er niet levend uit kwam.$B$BHadden Dark Iron-dwergen deze ring? Nou, dat legt een nieuwe laag samenzwering bovenop de negen lagen die al rondgaan. Misschien willen de autoriteiten dit weten. Aan iemand als ik is het verspild.$B$BGoed, terug naar de ring...",
  g = { {"stromen", "to flow, to surge"}, {"afdruk", "imprint"}, {"zegel", "seal"}, {"gegraveerd", "engraved (graveren)"}, {"initialen", "initials"}, {"eigenaar", "owner"}, {"zakenman", "businessman"}, {"koerier", "courier"}, {"huisbaas", "landlord"}, {"juwelier", "jeweller"}, {"vervloekte", "cursed"}, {"jeetje", "gosh, by golly"}, {"ervandoor ging", "ran off (ervandoor gaan)"}, {"ontwerp", "design"}, {"samenzwering", "conspiracy"}, {"autoriteiten", "authorities"}, {"verspild", "wasted (verspillen)"} },
},

[2843] = { en = "Gnomer-gooooone!", tier = 2,
  t = "Gnomer-weeeeeg!",
  d = "Zolang je de transponder bij je hebt, hoef je alleen maar op het platform te stappen. Dan word je naar Gnomeregan geteleporteerd.$B$BMisschien merk je wat vreemde bijwerkingen, maar die zouden niet blijvend moeten zijn... niet meer.$B$BIk vergat bijna het belangrijkste: terugkomen. Als je klaar bent om terug te komen, stap je gewoon op het transpolyporter-platform in Gnomeregan!$B$BNu moet ik de transponder nog afstellen op jouw grootte en gewicht.$b",
  o = "Wacht tot Scooty de Goblin Transponder heeft afgesteld.",
  p = "Hij is klaar!",
  c = "Helemaal klaar! Als je zover bent, stap je gewoon op het platform.",
  e = "Goblin Transponder",
  g = { {"zolang", "as long as"}, {"platform", "pad, platform"}, {"geteleporteerd", "teleported (teleporteren)"}, {"bijwerkingen", "side effects"}, {"blijvend", "permanent"}, {"afstellen", "to calibrate, to adjust"}, {"afgesteld", "calibrated (afstellen)"}, {"grootte", "size"}, {"gewicht", "weight"} },
},

[2929] = { en = "The Grand Betrayal", tier = 2,
  t = "Het grote verraad",
  d = "Ik vertrouwde Thermaplugg, $r. Ik had nooit gedacht dat hij mij en het hele gnomenvolk zou verraden. En waarvoor? Macht? Rijkdom? Dat had hij met de tijd allemaal gekregen. Nu zijn we uit ons thuis verdreven en heeft die gek de macht. De koning van niets....$B$BWe gaan Gnomeregan terugveroveren, $N. We stoppen niet tot de stad weer in onze handen is. Wil je meedoen aan onze strijd? Dan vraag ik je één simpele taak: dood de verrader. Vernietig Mekgineer Thermaplugg.",
  o = "Ga naar Gnomeregan en dood Mekgineer Thermaplugg. Ga terug naar High Tinker Mekkatorque als de taak klaar is.",
  p = "Is de taak klaar? Smeekte hij om mildheid? Om genade??",
  c = "Ik denk graag dat het laatste wat door zijn hoofd ging toen hij op de grond viel, jouw voet was, $R. Nu Thermaplugg dood is, zijn onze plannen om Gnomeregan terug te veroveren een stap dichter bij de werkelijkheid.",
  g = { {"verraad", "betrayal"}, {"verraden", "to betray"}, {"gnomenvolk", "gnomish people"}, {"rijkdom", "wealth"}, {"verdreven", "driven out (verdrijven)"}, {"terugveroveren", "to retake, to reconquer"}, {"strijd", "fight, struggle"}, {"verrader", "traitor, betrayer"}, {"vernietig", "destroy (vernietigen)"}, {"smeekte", "begged (smeken)"}, {"mildheid", "leniency"}, {"genade", "mercy"}, {"werkelijkheid", "reality"} },
},

})

